"""Reproduce the Oct 2 ledger review count of commit strings absent from the export."""
import json
import re
import sys

LOG = sys.argv[1] if len(sys.argv) > 1 else "/tmp/ledger-forensics/main-94a3dc95-log.txt"
CUTOFF = "2026-10-02T12:56"

rows = [json.loads(l) for l in open("/tmp/ledger-forensics/live/export-all.jsonl")]
issues = [r for r in rows if r.get("_type") == "issue"]
oct2 = {r["id"] for r in issues if r.get("created_at", "") < CUTOFF}
live = {r["id"] for r in issues}

commits = []
for rec in open(LOG, encoding="utf-8", errors="replace").read().split("\x1e")[1:]:
    sha, date, parents, body = rec.split("\x1f", 3)
    commits.append((sha, date, parents, body))

patterns = {
    "A_word": r"astro-plan-[A-Za-z0-9][A-Za-z0-9._-]*",
    "B_lower_dot": r"astro-plan-[a-z0-9]+(?:\.[0-9]+)*",
    "C_lower_dash": r"astro-plan-[a-z0-9][a-z0-9.\-]*[a-z0-9]",
    "D_bounded": r"\bastro-plan-[a-z0-9]+(?:\.[0-9]+)*\b",
}
for name, pat in patterns.items():
    rx = re.compile(pat)
    found = {}
    for sha, date, parents, body in commits:
        for m in rx.findall(body):
            m = m.rstrip(".-_")
            found.setdefault(m, []).append(sha)
    absent = sorted(s for s in found if s not in oct2)
    absent_live = sorted(s for s in found if s not in live)
    print(name, "distinct", len(found), "absent_oct2", len(absent), "absent_live", len(absent_live))

sources.store_census.py:
"""Run read-only SELECT queries against every isolated scratch store and record results.

Usage: python3 store_census.py <out.json> <store-dir> [...]
Every query is a SELECT against a scratch copy under /tmp/ledger-forensics/stores.
"""
import json
import subprocess
import sys

needles = [l.strip() for l in open("/tmp/ledger-forensics/needles.txt") if l.strip()]
controls = {"astro-plan-qwvo", "astro-plan-kyo7", "astro-plan-p0ds", "astro-plan-is9s"}
targets = [n for n in needles if n not in controls]
in_list = ",".join("'" + t + "'" for t in targets)
ctl_list = ",".join("'" + c + "'" for c in sorted(controls))

QUERIES = {
    "branches": "SELECT name, hash, CAST(latest_commit_date AS CHAR) AS latest FROM dolt_branches",
    "remote_branches": "SELECT name, hash, CAST(latest_commit_date AS CHAR) AS latest FROM dolt_remote_branches",
    "remotes": "SELECT name, url FROM dolt_remotes",
    "log_main": "SELECT COUNT(*) AS commits, CAST(MIN(date) AS CHAR) AS first, CAST(MAX(date) AS CHAR) AS last, "
                "SUM(date >= '2026-07-31' AND date < '2026-09-16') AS gap_commits FROM dolt_log",
    "log_all": "SELECT COUNT(*) AS commits, SUM(date >= '2026-07-31' AND date < '2026-09-16') AS gap_commits FROM dolt_log('--all')",
    "issues": "SELECT COUNT(*) AS n, MAX(created_at) AS max_created, MAX(updated_at) AS max_updated, "
              "SUM(created_at >= '2026-07-31' AND created_at < '2026-09-16') AS gap_created, "
              "SUM(updated_at >= '2026-07-31' AND updated_at < '2026-09-16') AS gap_updated FROM issues",
    "issue_prefixes": "SELECT SUBSTRING_INDEX(id, '-', 2) AS prefix, COUNT(*) AS n FROM issues GROUP BY prefix ORDER BY n DESC LIMIT 5",
    "targets_in_issues": f"SELECT id, status, CAST(created_at AS CHAR) AS created FROM issues WHERE id IN ({in_list})",
    "controls_in_issues": f"SELECT id FROM issues WHERE id IN ({ctl_list})",
    "targets_in_wisps": f"SELECT id FROM wisps WHERE id IN ({in_list})",
    "wisp_count": "SELECT COUNT(*) AS n, MAX(created_at) AS max_created FROM wisps",
    "targets_in_history": f"SELECT DISTINCT id FROM dolt_history_issues WHERE id IN ({in_list})",
    "controls_in_history": f"SELECT DISTINCT id FROM dolt_history_issues WHERE id IN ({ctl_list})",
}


def run(store, sql):
    proc = subprocess.run(
        ["dolt", "sql", "--disable-auto-gc", "-r", "json", "-q", sql],
        cwd=store, capture_output=True, text=True, timeout=900,
    )
    if proc.returncode != 0:
        return {"error": (proc.stderr or proc.stdout).strip()[:400]}
    out = proc.stdout.strip()
    if not out:
        return {"rows": []}
    return json.loads(out)


def main():
    result = {}
    for store in sys.argv[2:]:
        assert store.startswith("/tmp/ledger-forensics/stores/"), store
        result[store] = {name: run(store, sql) for name, sql in QUERIES.items()}
        print(store, "done", flush=True)
    json.dump(result, open(sys.argv[1], "w"), indent=1)


if __name__ == "__main__":
    main()

sources.darc_scan.py:
"""Search every chunk in Dolt storage files for byte strings, reachable or not.

Usage: python3 darc_scan.py <needles-file> <out.jsonl> <file-or-dir> [...]

Reads Dolt archive (.darc) files and Noms table files (32-character base32 names
without extension). Archive layout follows dolthub/dolt go/store/nbs/archive.go:
byte spans, then an index of big-endian uint64 span end offsets, uint64 prefixes,
uint32 chunk-reference pairs and 12-byte suffixes, then metadata and a footer.
Chunks are zstd frames (with or without a dictionary span) or, from format 2, Snappy
blocks with a trailing CRC32 as in Noms table files.

It decompresses each chunk and reports which needles occur in which file. It reads
copies only and writes nothing beside its report on stdout.
"""
import json
import os
import struct
import sys
from compression import zstd

ARCHIVE_SIG = b"DOLTARC"
TABLE_MAGIC = bytes.fromhex("ffb5d8c22463ee50")  # Noms table file footer magic


def snappy_decompress(src):
    pos = 0
    length = 0
    shift = 0
    while True:
        b = src[pos]
        pos += 1
        length |= (b & 0x7F) << shift
        if b < 0x80:
            break
        shift += 7
    out = bytearray()
    while pos < len(src):
        tag = src[pos]
        pos += 1
        kind = tag & 3
        if kind == 0:
            n = tag >> 2
            if n >= 60:
                extra = n - 59
                n = int.from_bytes(src[pos:pos + extra], "little")
                pos += extra
            n += 1
            out += src[pos:pos + n]
            pos += n
            continue
        if kind == 1:
            n = ((tag >> 2) & 7) + 4
            off = ((tag >> 5) << 8) | src[pos]
            pos += 1
        elif kind == 2:
            n = (tag >> 2) + 1
            off = int.from_bytes(src[pos:pos + 2], "little")
            pos += 2
        else:
            n = (tag >> 2) + 1
            off = int.from_bytes(src[pos:pos + 4], "little")
            pos += 4
        start = len(out) - off
        for i in range(n):
            out.append(out[start + i])
    if len(out) != length:
        raise ValueError("snappy length mismatch")
    return bytes(out)


def archive_chunks(buf):
    version = buf[-8]
    if version >= 3:
        footer_size = 220
        base = len(buf) - footer_size
        idx_len = struct.unpack(">Q", buf[base:base + 8])[0]
        fields = base + 8
    else:
        footer_size = 216
        base = len(buf) - footer_size
        idx_len = struct.unpack(">I", buf[base:base + 4])[0]
        fields = base + 4
    span_count, chunk_count, meta_len = struct.unpack(">III", buf[fields:fields + 12])
    idx_start = base - meta_len - idx_len
    pos = idx_start
    ends = struct.unpack(f">{span_count}Q", buf[pos:pos + 8 * span_count])
    pos += 8 * span_count
    if ends and ends[-1] != idx_start:
        raise ValueError(f"span end {ends[-1]} != index start {idx_start}")
    pos += 8 * chunk_count  # prefixes
    refs = struct.unpack(f">{2 * chunk_count}I", buf[pos:pos + 8 * chunk_count])

    def span(i):
        start = 0 if i == 1 else ends[i - 2]
        return buf[start:ends[i - 1]]

    dicts = {}
    stats = {"version": version, "spans": span_count, "chunks": chunk_count, "zstd_dict": 0, "zstd_plain": 0, "snappy": 0}
    for k in range(chunk_count):
        dict_id, data_id = refs[2 * k], refs[2 * k + 1]
        data = span(data_id)
        if dict_id == 0:
            if version >= 2:
                stats["snappy"] += 1
                yield snappy_decompress(data[:-4]), stats
            else:
                stats["zstd_plain"] += 1
                yield zstd.decompress(data), stats
            continue
        d = dicts.get(dict_id)
        if d is None:
            d = zstd.ZstdDict(zstd.decompress(span(dict_id)))
            dicts[dict_id] = d
        stats["zstd_dict"] += 1
        yield zstd.decompress(data, zstd_dict=d), stats


def table_chunks(buf):
    if buf[-8:] != TABLE_MAGIC:
        raise ValueError("not a Noms table file")
    chunk_count = struct.unpack(">I", buf[-20:-16])[0]
    stats = {"version": "noms-table", "chunks": chunk_count, "snappy": 0}
    index_size = chunk_count * (12 + 4 + 12)
    idx_start = len(buf) - 20 - index_size
    lengths = struct.unpack(f">{chunk_count}I", buf[idx_start + 12 * chunk_count: idx_start + 16 * chunk_count])
    # Prefix tuples carry the ordinal; data lies in ordinal order.
    pos = 0
    for n in lengths:
        stats["snappy"] += 1
        yield snappy_decompress(buf[pos:pos + n - 4]), stats
        pos += n


def journal_chunks(buf):
    # Chunk journal (go/store/nbs/journal_record.go): uint32 length, tagged fields, uint32 CRC.
    stats = {"version": "journal", "chunks": 0, "snappy": 0, "root_records": 0}
    pos = 0
    while pos + 4 <= len(buf):
        length = struct.unpack(">I", buf[pos:pos + 4])[0]
        if length == 0 or pos + length > len(buf):
            break
        rec = buf[pos + 4:pos + length - 4]
        i = 0
        kind = None
        payload = None
        while i < len(rec):
            tag = rec[i]
            i += 1
            if tag == 1:
                kind = rec[i]
                i += 1
            elif tag == 2:
                i += 20
            elif tag == 4:
                i += 8
            elif tag == 3:
                payload = rec[i:]
                i = len(rec)
            else:
                raise ValueError(f"unknown journal tag {tag} at {pos}")
        if kind == 2 and payload is not None:
            stats["chunks"] += 1
            stats["snappy"] += 1
            yield snappy_decompress(payload[:-4]), stats
        elif kind == 1:
            stats["root_records"] += 1
        pos += length
    stats["parsed_bytes"] = pos


def scan(path, needles):
    buf = open(path, "rb").read()
    if buf[-7:] == ARCHIVE_SIG:
        gen = archive_chunks(buf)
    elif buf[-8:] == TABLE_MAGIC:
        gen = table_chunks(buf)
    else:
        gen = journal_chunks(buf)
    hits = {}
    stats = {}
    decoded = 0
    for raw, stats in gen:
        decoded += 1
        for n in needles:
            if n in raw:
                key = n.decode()
                hits[key] = hits.get(key, 0) + 1
    return {"file": path, "size": len(buf), "decoded": decoded, "stats": stats, "hits": hits}


def is_store_file(name):
    return name.endswith(".darc") or (len(name) == 32 and name.isalnum())


def main():
    needles = [l.strip().encode() for l in open(sys.argv[1]) if l.strip()]
    out = open(sys.argv[2], "w")
    targets = []
    for arg in sys.argv[3:]:
        if os.path.isdir(arg):
            for root, _dirs, files in os.walk(arg):
                targets += sorted(os.path.join(root, f) for f in files if is_store_file(f))
        else:
            targets.append(arg)
    for t in targets:
        try:
            out.write(json.dumps(scan(t, needles)) + "\n")
        except Exception as exc:  # report and continue: one bad file must not hide the rest
            out.write(json.dumps({"file": t, "error": repr(exc)}) + "\n")
    out.close()


if __name__ == "__main__":
    main()

sources.compare_ids.py:
"""Dump issue, dependency and comment keys from each scratch store and compare by ID.

Usage: python3 compare_ids.py <out.json>
"""
import json
import subprocess
import sys

STORES = {
    "backup_20261016": "/tmp/ledger-forensics/stores/backup-20261016",
    "remote_current_c928cda": "/tmp/ledger-forensics/stores/remote-current-c928cda",
    "remote_pre_migration_b8d4879": "/tmp/ledger-forensics/stores/remote-pre-migration-b8d4879",
    "clone_platevault_claude_20260826": "/tmp/ledger-forensics/stores/claude-embedded",
    "clone_platevault_sol_20260827": "/tmp/ledger-forensics/stores/sol-dolt",
    "clone_clean_room_pv_20260827": "/tmp/ledger-forensics/stores/cleanroom-pv",
}
Q_ISSUES = "SELECT id, status, assignee, CAST(created_at AS CHAR) AS created_at, CAST(updated_at AS CHAR) AS updated_at, title FROM issues"
Q_DEPS = ("SELECT issue_id, COALESCE(depends_on_issue_id, depends_on_wisp_id, depends_on_external) AS depends_on_id, type FROM dependencies",
          "SELECT issue_id, depends_on_id, type FROM dependencies")
Q_COMMENTS = "SELECT issue_id, COUNT(*) AS n FROM comments GROUP BY issue_id"


def q(store, sql):
    p = subprocess.run(["dolt", "sql", "--disable-auto-gc", "-r", "json", "-q", sql], cwd=store,
                       capture_output=True, text=True, timeout=900)
    if p.returncode != 0:
        raise RuntimeError(p.stderr[:300])
    return json.loads(p.stdout or '{"rows": []}').get("rows", [])


def load_export(path):
    rows = [json.loads(l) for l in open(path)]
    issues = {r["id"]: r for r in rows if r.get("_type", "issue") == "issue" and "id" in r}
    deps = {(d["issue_id"], d["depends_on_id"], d.get("type")) for r in issues.values() for d in (r.get("dependencies") or [])}
    comments = {r["id"]: len(r.get("comments") or []) for r in issues.values() if r.get("comments")}
    return issues, deps, comments


data = {}
for name, store in STORES.items():
    issues = {r["id"]: r for r in q(store, Q_ISSUES)}
    try:
        dep_rows = q(store, Q_DEPS[0])
    except RuntimeError:
        dep_rows = q(store, Q_DEPS[1])
    deps = {(r["issue_id"], r["depends_on_id"], r["type"]) for r in dep_rows}
    comments = {r["issue_id"]: int(r["n"]) for r in q(store, Q_COMMENTS)}
    data[name] = (issues, deps, comments)
data["live_export_all_20261016"] = load_export("/tmp/ledger-forensics/live/export-all.jsonl")
data["oct2_export_ledger_refreshed"] = load_export("/tmp/ledger-forensics/oct2-review/.audit-smoke/ledger-refreshed.jsonl")

live_i, live_d, live_c = data["live_export_all_20261016"]
summary = {}
for name, (issues, deps, comments) in data.items():
    ids = set(issues)
    lids = set(live_i)
    status_diff = sorted(i for i in ids & lids if issues[i].get("status") != live_i[i].get("status"))
    summary[name] = {
        "issues": len(ids),
        "dependencies": len(deps),
        "issues_with_comments": len(comments),
        "comments": sum(comments.values()),
        "ids_not_in_live": sorted(ids - lids),
        "live_ids_not_here": len(lids - ids),
        "status_differs_from_live": len(status_diff),
        "status_differs_sample": status_diff[:10],
        "deps_not_in_live": len(deps - live_d),
        "comment_count_differs_from_live": sorted(i for i in set(comments) | set(live_c) if i in ids and i in lids and comments.get(i, 0) != live_c.get(i, 0))[:20],
    }
extra = {}
for name, (issues, _d, _c) in data.items():
    for i in sorted(set(issues) - set(live_i)):
        r = issues[i]
        extra.setdefault(name, []).append({k: r.get(k) for k in ("id", "status", "created_at", "updated_at", "title")})
json.dump({"summary": summary, "rows_not_in_live": extra}, open(sys.argv[1], "w"), indent=1)
for k, v in summary.items():
    print(k, {x: (y if not isinstance(y, list) else (len(y), y[:4])) for x, y in v.items()})
